class PetitModele(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.layers = torch.nn.ModuleList([
            torch.nn.Linear(8, 8),
            torch.nn.Linear(8, 3),
        ])
        self.register_buffer("mean", torch.zeros(8))

    def forward(self, x):
        x = x - self.mean
        x = torch.relu(self.layers[0](x))
        return self.layers[1](x)
